data.minimal_example:
final request = PaystackTransactionRequest(reference: 'ref', secretKey: 'sk', email: 'user@example.com', amount: 1500, currency: PaystackCurrency.ngn, channel: [PaystackPaymentChannel.card]);
final init = await PaymentService.initializeTransaction(request);
if (init.status) await PaymentService.showPaymentModal(context, transaction: init, callbackUrl: 'https://example.com/callback');
